#include "htb/engine.h"
#include <assert.h>
#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#undef assert
#define assert(condition) do { if (!(condition)) { fprintf(stderr,"CHECK failed: %s (%s:%d)\n",#condition,__FILE__,__LINE__); abort(); } } while(0)

static void parse(htb_scalar*x,const char*s){char e[160]={0};assert(htb_scalar_parse_rational(x,s,e,sizeof(e)));}
static void configure_tiling(htb_tiling_config*c,const char*cx,const char*cy){memset(c,0,sizeof(*c));snprintf(c->id,sizeof(c->id),"elliptical-square");snprintf(c->version,sizeof(c->version),"1");c->parameter_count=2;snprintf(c->parameters[0].key,sizeof(c->parameters[0].key),"centerX");snprintf(c->parameters[0].value,sizeof(c->parameters[0].value),"%s",cx);snprintf(c->parameters[1].key,sizeof(c->parameters[1].key),"centerY");snprintf(c->parameters[1].value,sizeof(c->parameters[1].value),"%s",cy);}

static void test_tiling_provider(htb_backend_kind kind){
    htb_arith_ctx ctx;char error[256]={0};assert(htb_arith_ctx_init(&ctx,kind,256,2048,error,sizeof(error)));htb_tiling_config config;configure_tiling(&config,"1/2","-2/3");htb_tiling tiling;assert(htb_tiling_init(&tiling,&ctx,&config,error,sizeof(error)));
    htb_vec2 reference,disk,roundtrip,n,v,out;htb_vec2_init(&ctx,&reference);htb_vec2_init(&ctx,&disk);htb_vec2_init(&ctx,&roundtrip);htb_vec2_init(&ctx,&n);htb_vec2_init(&ctx,&v);htb_vec2_init(&ctx,&out);parse(&reference.x,"7/3");parse(&reference.y,"-5/4");assert(tiling.definition->ops.from_reference(&tiling,&reference,&disk,error,sizeof(error)));assert(tiling.definition->ops.to_reference(&tiling,&disk,&roundtrip,error,sizeof(error)));assert(fabs(htb_scalar_get_approx(&roundtrip.x)-7.0/3.0)<1e-20);assert(fabs(htb_scalar_get_approx(&roundtrip.y)+1.25)<1e-20);
    htb_point_location location;htb_point_location_init(&location);assert(tiling.definition->ops.locate_point(&tiling,&disk,&location,error,sizeof(error)));assert(strcmp(location.tile.key,"elliptical-square:2,-2")==0);assert(location.tile.coordinate_count==2&&location.tile.coordinates[0]==2&&location.tile.coordinates[1]==-2);htb_adjacency_list neighbors;htb_adjacency_list_init(&neighbors);assert(htb_tiling_neighbors(&tiling,&location.tile,&neighbors,error,sizeof(error)));assert(neighbors.count==4);for(size_t i=0;i<neighbors.count;i++){htb_adjacency reverse;assert(tiling.definition->ops.adjacent(&tiling,&neighbors.items[i].neighbor,&neighbors.items[i].neighbor_edge,&reverse,error,sizeof(error)));assert(htb_tile_id_equal(&reverse.neighbor,&location.tile));assert(strcmp(reverse.source_edge.boundary_key,neighbors.items[i].source_edge.boundary_key)==0);}
    parse(&v.x,"2");parse(&v.y,"3");assert(tiling.definition->ops.normal_at(&tiling,&neighbors.items[0].source_edge,&disk,&n,error,sizeof(error)));assert(htb_negative_refract(&out,&v,&n));double before=13,after=pow(htb_scalar_get_approx(&out.x),2)+pow(htb_scalar_get_approx(&out.y),2);assert(fabs(before-after)<1e-12);
    htb_scalar area;htb_scalar_init(&ctx,&area);assert(tiling.definition->ops.tile_measure(&tiling,&location.tile,HTB_MEASURE_REFERENCE_EUCLIDEAN_AREA,&area,error,sizeof(error)));assert(htb_scalar_compare_si(&area,1)==HTB_CMP_EQUAL);htb_scalar_clear(&area);
    htb_adjacency_list_clear(&neighbors);htb_point_location_clear(&location);htb_vec2_clear(&reference);htb_vec2_clear(&disk);htb_vec2_clear(&roundtrip);htb_vec2_clear(&n);htb_vec2_clear(&v);htb_vec2_clear(&out);htb_tiling_clear(&tiling);htb_arith_ctx_clear(&ctx);
}

static void base_request(htb_run_request*r,const char*du,const char*dv){memset(r,0,sizeof(*r));snprintf(r->run_id,sizeof(r->run_id),"native-test");r->backend=HTB_BACKEND_CALCIUM;configure_tiling(&r->tiling,"1/2","1/2");r->initial_precision=256;r->max_precision=2048;r->memory_limit_mb=1024;r->trajectory_count=1;htb_trajectory_input*in=&r->trajectories[0];snprintf(in->id,sizeof(in->id),"A");snprintf(in->start_u,sizeof(in->start_u),"0");snprintf(in->start_v,sizeof(in->start_v),"0");snprintf(in->direction_u,sizeof(in->direction_u),"%s",du);snprintf(in->direction_v,sizeof(in->direction_v),"%s",dv);in->bounces=2;}
static void test_vertex(void){htb_run_request q;base_request(&q,"1","1");htb_run_result r;assert(htb_run(&q,&r,NULL,NULL));assert(r.trajectories[0].status==HTB_STATUS_VERTEX);assert(r.trajectories[0].event_count==0);assert(r.trajectories[0].competing_count==2);htb_run_result_clear(&r);}
static void test_near_vertex(void){const char*plus[]={"1000001/1000000","1000000000001/1000000000000","1000000000000000000000001/1000000000000000000000000"};const char*minus[]={"999999/1000000","999999999999/1000000000000","999999999999999999999999/1000000000000000000000000"};for(int k=0;k<3;k++){htb_run_request a,b;base_request(&a,"1",plus[k]);base_request(&b,"1",minus[k]);htb_run_result x,y;assert(htb_run(&a,&x,NULL,NULL));assert(htb_run(&b,&y,NULL,NULL));assert(x.trajectories[0].event_count>0&&y.trajectories[0].event_count>0);assert(strcmp(x.trajectories[0].events[0].edge.label,"top")==0);assert(strcmp(y.trajectories[0].events[0].edge.label,"right")==0);htb_run_result_clear(&x);htb_run_result_clear(&y);}}
static void test_manifest_contract(void){char error[160]={0};htb_tiling_config c;memset(&c,0,sizeof(c));snprintf(c.id,sizeof(c.id),"elliptical-square");assert(htb_tiling_config_normalize(&c,error,sizeof(error)));assert(strcmp(c.version,"1")==0);assert(c.parameter_count==2);snprintf(c.parameters[0].key,sizeof(c.parameters[0].key),"notAParameter");assert(!htb_tiling_config_normalize(&c,error,sizeof(error)));assert(strstr(error,"unknown parameter"));}

int main(void){assert(htb_tiling_definition_count()==1);const htb_tiling_definition*d=htb_tiling_definition_find("elliptical-square");assert(d&&d->tile_type_count==1&&d->tile_types[0].side_count==4);test_manifest_contract();test_tiling_provider(HTB_BACKEND_ARB);test_tiling_provider(HTB_BACKEND_CALCIUM);test_vertex();test_near_vertex();puts("native core tests passed");return 0;}
